// Command sen-sbom-inventory serves the HTTP API described in README.md.
package main

import (
	"log"
	"os"

	"github.com/xjeey8iust/sen-sbom-inventory/internal/api"
	"github.com/xjeey8iust/sen-sbom-inventory/internal/store"
)

func main() {
	address := os.Getenv("ADDR")
	if address == "" {
		address = "127.0.0.1:8080"
	}
	databasePath := os.Getenv("DB_PATH")
	if databasePath == "" {
		databasePath = "sen-sbom-inventory.db"
	}

	st, err := store.Open(databasePath)
	if err != nil {
		log.Fatalf("open store: %v", err)
	}
	defer st.Close()

	if err := api.NewRouter(st).Run(address); err != nil {
		log.Fatalf("serve: %v", err)
	}
}

package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/xjeey8iust/sen-sbom-inventory/internal/store"
)

// sbomHandlers bundles the HTTP handlers with their storage dependency.
type sbomHandlers struct {
	store *store.Store
}

// NewRouter wires the public HTTP surface. Every entry keeps the error shape
// the service contract in README.md describes.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	h := &sbomHandlers{store: st}

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	router.POST("/sboms", h.register)
	router.GET("/sboms", h.list)

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

// Package model defines the SBOM inventory domain types and the errors shared
// between the HTTP layer and the storage layer.
package model

import "errors"

// Component is one entry of a bill of materials. Coordinate is unique within
// a single SBOM; Dependencies refer to coordinates of other components in the
// same SBOM.
type Component struct {
	Coordinate   string   `json:"coordinate"`
	License      string   `json:"license"`
	Dependencies []string `json:"dependencies"`
}

// SBOM is the persisted manifest. ID is assigned by the store; Artifact and
// Version together identify a manifest for idempotent registration.
type SBOM struct {
	ID         int64       `json:"id"`
	Artifact   string      `json:"artifact"`
	Version    string      `json:"version"`
	Components []Component `json:"components"`
}

// Sentinel errors. The HTTP layer maps each sentinel to a status code and uses
// the error type name as the business error code.
var (
	// ErrInvalidInput signals a request the caller can fix: malformed body,
	// missing fields, duplicates, dangling dependency targets, bad paging, ...
	ErrInvalidInput = errors.New("InvalidSbomInputError")
	// ErrConflict signals that an SBOM with the same artifact and version
	// already exists with different content.
	ErrConflict = errors.New("SbomConflictError")
	// ErrStorageUnavailable signals that the persistence layer cannot serve
	// the request.
	ErrStorageUnavailable = errors.New("storage_unavailable")
)

