321	
322		rec = getSBOMs(t, router, "/sboms?artifact=App")
323		var page listResponse
324		decodeBody(t, rec, &page)
325		if page.Total != 1 {
326			t.Fatalf("case-sensitive filter total = %d, want 1", page.Total)
327		}
328	}
