475	func TestConcurrentIdenticalRegistersShareOneRecord(t *testing.T) {
476		router, _ := newTestRouter(t)
477		body := `{"artifact":"race","version":"1","components":[
478			{"coordinate":"a","license":"L","dependencies":["b"]},
479			{"coordinate":"b","license":"L","dependencies":[]}
480		]}`
481		const n = 8
482		var wg sync.WaitGroup
483		ids := make(chan int64, n)
484		statuses := make(chan int, n)
485		for i := 0; i < n; i++ {
486			wg.Add(1)
487			go func() {
488				defer wg.Done()
489				rec := postSBOM(t, router, body)
490				statuses <- rec.Code
491				if rec.Code == http.StatusCreated {
492					var got model.SBOM
493					json.Unmarshal(rec.Body.Bytes(), &got)
494					ids <- got.ID
495				}
496			}()
497		}
498		wg.Wait()
499		close(ids)
500		close(statuses)
501	
502		first := int64(-1)
503		for status := range statuses {
504			if status != http.StatusCreated {
505				t.Fatalf("concurrent register status = %d, want 201", status)
506			}
507		}
508		count := 0
509		for id := range ids {
510			if first == -1 {
511				first = id
512			} else if id != first {
513				t.Fatalf("concurrent registers produced ids %d and %d", first, id)
514			}
515			count++
516		}
517		if count != n {
518			t.Fatalf("created responses = %d, want %d", count, n)
519		}
520	}
