70				v := fmt.Sprintf("%02d", i)
71				body := fmt.Sprintf(`{"artifact":"app","version":"%s","components":[
72					{"coordinate":"a","license":"A","dependencies":["b"]},
73					{"coordinate":"b","license":"B","dependencies":[]}
74				]}`, v)
75				register(router, "app", v, body)
76			}
77			// A different artifact whose components share coordinates; never part
78			// of an "app" page.
79			register(router, "other", "1", `{"artifact":"other","version":"1","components":[
80				{"coordinate":"a","license":"SECRET","dependencies":[]}
81			]}`)
82			counted.Reset()
83	
84			rec := getSBOMs(t, router, "/sboms?artifact=app&pageSize=100")
85			if rec.Code != http.StatusOK {
86				t.Fatalf("status = %d, body %s", rec.Code, rec.Body.String())
87			}
88			counters := counted.Snapshot()
89			if counters.Selects != 4 {
90				t.Fatalf("100-item request issued %d SELECTs, want exactly 4", counters.Selects)
