92			if counters.RowsByKind["sboms"] != 100 ||
93				counters.RowsByKind["components"] != 200 ||
94				counters.RowsByKind["dependencies"] != 100 {
95				t.Fatalf("detail reads escaped the page/artifact: %+v", counters.RowsByKind)
96			}
97	
98			var got listResponse
99			decodeBody(t, rec, &got)
100			if got.Total != 100 || len(got.Items) != 100 {
101				t.Fatalf("total/items = %d/%d", got.Total, len(got.Items))
102			}
103			for _, item := range got.Items {
104				if item.Artifact != "app" {
105					t.Fatalf("foreign item on page: %q", item.Artifact)
106				}
107				for _, c := range item.Components {
108					if c.License == "SECRET" {
109						t.Fatalf("other artifact's component leaked: %+v", c)
110					}
111				}
112			}
113		})
114	
115		t.Run("empty page", func(t *testing.T) {
116			router, counted := newCountedRouter(t)
117			register(router, "app", "1", `{"artifact":"app","version":"1","components":[]}`)
118			counted.Reset()
119	
120			// Unknown artifact: count plus page scan, and the detail queries must
121			// not run against an empty IN-list.
122			rec := getSBOMs(t, router, "/sboms?artifact=ghost")
123			if rec.Code != http.StatusOK {
124				t.Fatalf("status = %d", rec.Code)
125			}
126			counters := counted.Snapshot()
127			if counters.Selects > 4 {
128				t.Fatalf("SELECTs = %d, want at most 4", counters.Selects)
129			}
130			if counters.Selects != 2 || counters.RowsByKind["components"] != 0 || counters.RowsByKind["dependencies"] != 0 {
131				t.Fatalf("empty page issued %d selects, rows %+v; want 2 and no details",
132					counters.Selects, counters.RowsByKind)
