1	package store
2	
3	import (
4		"context"
5		"errors"
6		"strings"
7		"testing"
8	
9		"github.com/xjeey8iust/sen-sbom-inventory/internal/model"
10	)
11	
12	// twoComponentsWithDep is the canonical manifest used by the lifecycle tests:
13	// two components and one dependency edge, so both detail tables hold rows.
14	func twoComponentsWithDep() []model.Component {
15		return twoComponents([]string{"b"})
16	}
17	
18	// TestRegisterDetailWriteFailureRollsBack forces each detail-write step
19	// (component insert and dependency insert) to fail once. The failed
20	// registration must surface model.ErrStorageUnavailable, leave no partial
21	// record, and once the fault is gone the same registration must complete and
22	// read back whole — proving the rollback ran, the connection was returned and
23	// the unified lifecycle recovers.
24	func TestRegisterDetailWriteFailureRollsBack(t *testing.T) {
25		for _, kind := range []string{"components", "dependencies"} {
26			t.Run(kind, func(t *testing.T) {
27				st, counted := openCountingStore(t)
28				ctx := context.Background()
29	
30				// A pre-existing, unrelated manifest that must survive the failure.
31				registerManifest(t, st, "other", "1", []model.Component{
32					{Coordinate: "keep", License: "K", Dependencies: []string{}},
33				})
34				counted.Reset()
35	
36				counted.FailNextWrite(kind)
37				sbom, created, err := st.Register(ctx, &model.SBOM{
38					Artifact: "app", Version: "1", Components: twoComponentsWithDep(),
39				})
40				if err == nil {
41					t.Fatalf("expected %s write failure", kind)
42				}
43				if !errors.Is(err, model.ErrStorageUnavailable) {
44					t.Fatalf("error = %v, want model.ErrStorageUnavailable", err)
45				}
46				if sbom != nil || created {
47					t.Fatalf("failed register returned sbom=%v created=%v", sbom, created)
48				}
49	
50				// The fault was one-shot; reset counters, then prove no partial
51				// record is visible under the failed key.
52				counted.Reset()
53				items, total, err := st.List(ctx, "app", 1, 20)
54				if err != nil {
55					t.Fatalf("list after failed register: %v", err)
56				}
57				if total != 0 || len(items) != 0 {
58					t.Fatalf("partial registration visible: total=%d items=%d", total, len(items))
59				}
60	
61				// The unrelated manifest is untouched.
62				others, otherTotal, err := st.List(ctx, "other", 1, 20)
63				if err != nil {
64					t.Fatalf("list other: %v", err)
65				}
66				if otherTotal != 1 || len(others) != 1 || len(others[0].Components) != 1 {
67					t.Fatalf("unrelated manifest changed: total=%d items=%d", otherTotal, len(others))
68				}
69	
70				// Fault cleared: the same registration now completes normally.
71				got, created, err := st.Register(ctx, &model.SBOM{
72					Artifact: "app", Version: "1", Components: twoComponentsWithDep(),
73				})
74				if err != nil {
75					t.Fatalf("register after recovery: %v", err)
76				}
77				if !created {
78					t.Fatalf("register after recovery was not created")
79				}
80	
81				// The recovered manifest reads back complete from one snapshot.
82				items, total, err = st.List(ctx, "app", 1, 20)
83				if err != nil {
84					t.Fatalf("list after recovery: %v", err)
85				}
86				if total != 1 || len(items) != 1 {
87					t.Fatalf("total/items after recovery = %d/%d, want 1/1", total, len(items))
88				}
89				assertSameManifest(t, got, items[0])
90				if len(items[0].Components) != 2 {
91					t.Fatalf("recovered manifest incomplete: %+v", items[0])
92				}
93				deps := map[string][]string{}
94				for _, c := range items[0].Components {
95					deps[c.Coordinate] = c.Dependencies
96				}
97				if len(deps["a"]) != 1 || deps["a"][0] != "b" {
98					t.Fatalf("recovered dependency edge missing: %+v", deps)
99				}
100			})
101		}
102	}
103	
104	// TestRollbackFailureKeepsOriginalError forces a detail-write failure and a
105	// ROLLBACK failure together. The cleanup error must be swallowed: the caller
106	// still sees the original storage error, the transaction is actually undone
107	// (no partial record) and the connection stays usable afterwards.
108	func TestRollbackFailureKeepsOriginalError(t *testing.T) {
109		st, counted := openCountingStore(t)
110		ctx := context.Background()
111		registerManifest(t, st, "app", "1", twoComponentsWithDep())
112	
113		counted.FailNextWrite("components")
114		counted.FailNextRollback()
115	
116		_, _, err := st.Register(ctx, &model.SBOM{
117			Artifact: "app", Version: "2", Components: twoComponentsWithDep(),
118		})
119		if !errors.Is(err, model.ErrStorageUnavailable) {
120			t.Fatalf("error = %v, want model.ErrStorageUnavailable", err)
121		}
122		if !strings.Contains(err.Error(), "forced write failure") {
123			t.Fatalf("error lost the original write cause: %v", err)
124		}
125		if strings.Contains(err.Error(), "forced rollback failure") {
126			t.Fatalf("rollback cleanup error overwrote the storage error: %v", err)
127		}
