1	// Package storetest provides test infrastructure for the SBOM service: a
2	// database/sql driver that wraps the real SQLite driver and counts the
3	// statements a request actually issues, optionally forcing read failures.
4	// It wraps the genuine driver end to end rather than mocking internals.
5	package storetest
6	
7	import (
8		"context"
9		"database/sql"
10		"database/sql/driver"
11		"errors"
12		"strings"
13		"sync"
14	
15		sqlitedriver "modernc.org/sqlite"
16	)
17	
18	// Counters summarizes the SELECTs observed by the counting driver.
19	type Counters struct {
20		// Selects is the total number of SELECT statements executed.
21		Selects int
22		// RowsByKind is the number of result rows returned, keyed by statement
23		// kind: "count", "sboms", "components", "dependencies".
24		RowsByKind map[string]int
25	}
26	
27	// Driver is a database/sql/driver.Driver wrapping the genuine SQLite driver.
28	// A single registration is shared by every connection, so counters cover a
29	// whole request even when database/sql reuses pooled connections.
30	type Driver struct {
31		inner driver.Driver
32		mu    sync.Mutex
33		stats struct {
34			selects    int
35			rowsByKind map[string]int
36		}
37		// failKind, when non-empty, makes the next SELECT of that kind fail.
38		failKind string
39		// failWriteKind, when non-empty, makes the next INSERT of that kind
40		// ("sboms"/"components"/"dependencies") fail, whether it is issued
41		// directly or through a prepared statement.
42		failWriteKind string
43		// failRollback makes the next ROLLBACK report failure.
44		failRollback bool
45	}
46	
47	// DriverName is the database/sql name under which the counting driver is
48	// registered.
49	const DriverName = "sqlite-counttest"
50	
51	var (
52		once   sync.Once
53		shared *Driver
54	)
55	
56	// Register registers the shared counting driver once and returns it,
57	// resetting its counters. Each test package runs in its own binary, so the
58	// fixed name does not collide across packages.
59	func Register() *Driver {
60		once.Do(func() {
61			shared = &Driver{inner: &sqlitedriver.Driver{}}
62			sql.Register(DriverName, shared)
63		})
64		shared.Reset()
65		return shared
66	}
67	
68	// Reset clears the observed counters and every pending fault.
69	func (d *Driver) Reset() {
70		d.mu.Lock()
71		d.stats.selects = 0
72		d.stats.rowsByKind = map[string]int{}
73		d.failKind = ""
74		d.failWriteKind = ""
75		d.failRollback = false
76		d.mu.Unlock()
77	}
78	
79	// FailNextRead makes the next SELECT of kind
80	// ("count"/"sboms"/"components"/"dependencies") fail at the driver,
81	// simulating a storage read error.
82	func (d *Driver) FailNextRead(kind string) {
83		d.mu.Lock()
84		d.failKind = kind
85		d.mu.Unlock()
86	}
87	
88	// FailNextWrite makes the next INSERT of kind
89	// ("sboms"/"components"/"dependencies") fail, simulating a storage write
90	// error during one detail-write step of a registration.
91	func (d *Driver) FailNextWrite(kind string) {
92		d.mu.Lock()
93		d.failWriteKind = kind
94		d.mu.Unlock()
95	}
96	
97	// FailNextRollback makes the next ROLLBACK statement report failure, so tests
98	// can prove transaction-cleanup errors never overwrite the error that
99	// triggered the rollback.
100	func (d *Driver) FailNextRollback() {
101		d.mu.Lock()
102		d.failRollback = true
103		d.mu.Unlock()
104	}
105	
106	// Snapshot returns a point-in-time copy of the counters.
107	func (d *Driver) Snapshot() Counters {
108		d.mu.Lock()
109		defer d.mu.Unlock()
110		rows := make(map[string]int, len(d.stats.rowsByKind))
111		for k, v := range d.stats.rowsByKind {
112			rows[k] = v
113		}
114		return Counters{Selects: d.stats.selects, RowsByKind: rows}
115	}
116	
117	func (d *Driver) Open(name string) (driver.Conn, error) {
118		raw, err := d.inner.Open(name)
119		if err != nil {
120			return nil, err
121		}
122		return &countingConn{Conn: raw, driver: d}, nil
123	}
124	
125	// countingConn exposes the same legacy driver.Execer/driver.Queryer surface
126	// database/sql uses with the modernc driver; statements flow through Exec and
127	// Query where the counter lives.
128	type countingConn struct {
129		driver.Conn
130		driver *Driver
131	}
132	
133	func (c *countingConn) Exec(query string, args []driver.Value) (driver.Result, error) {
134		if isRollback(query) {
135			// Always run the real ROLLBACK first: the connection must actually
136			// leave its transaction before going back to the pool. The synthetic
137			// failure only reports what the store must learn to ignore.
138			res, err := c.Conn.(driver.Execer).Exec(query, args)
139			c.driver.mu.Lock()
140			fail := c.driver.failRollback
141			c.driver.failRollback = false
142			c.driver.mu.Unlock()
143			if fail {
144				return res, errors.New("forced rollback failure from test driver")
145			}
146			return res, err
147		}
148		if err := c.checkExecFault(query); err != nil {
149			return nil, err
150		}
151		return c.Conn.(driver.Execer).Exec(query, args)
152	}
153	
154	// Prepare wraps prepared statements too: the store batches the component and
155	// dependency inserts through a prepared statement, so a write fault has to be
156	// visible on that path and not only for direct Exec calls.
157	func (c *countingConn) Prepare(query string) (driver.Stmt, error) {
158		raw, err := c.Conn.Prepare(query)
159		if err != nil {
160			return nil, err
161		}
162		return &countingStmt{Stmt: raw, driver: c.driver, query: query}, nil
163	}
164	
165	// ResetSession and IsValid delegate the optional driver interfaces so pooled
166	// connections behave under the wrapper exactly as with the raw driver.
167	func (c *countingConn) ResetSession(ctx context.Context) error {
168		if resetter, ok := c.Conn.(driver.SessionResetter); ok {
169			return resetter.ResetSession(ctx)
170		}
171		return nil
172	}
173	
174	func (c *countingConn) IsValid() bool {
175		if validator, ok := c.Conn.(driver.Validator); ok {
176			return validator.IsValid()
177		}
178		return true
179	}
180	
181	func (c *countingConn) Query(query string, args []driver.Value) (driver.Rows, error) {
182		kind := SelectKind(query)
183		if kind != "" {
184			c.driver.mu.Lock()
185			fail := c.driver.failKind == kind
186			if fail {
187				// A one-shot fault: consume it so only the next matching read fails.
188				c.driver.failKind = ""
189			}
190			c.driver.mu.Unlock()
191			if fail {
192				return nil, errors.New("forced read failure from test driver")
193			}
194		}
195		rows, err := c.Conn.(driver.Queryer).Query(query, args)
196		if err != nil || kind == "" {
197			return rows, err
198		}
199		c.driver.mu.Lock()
200		c.driver.stats.selects++
201		c.driver.mu.Unlock()
202		return &countingRows{Rows: rows, driver: c.driver, kind: kind}, nil
203	}
204	
205	// checkExecFault consumes any pending write fault for the statement and
206	// returns the synthetic error when one fires. Callers must route ROLLBACK
207	// elsewhere: that path runs the real rollback before reporting its synthetic
208	// failure so a pooled connection never stays inside an open transaction.
209	func (c *countingConn) checkExecFault(query string) error {
210		if kind := WriteKind(query); kind != "" {
211			c.driver.mu.Lock()
212			fire := c.driver.failWriteKind == kind
213			if fire {
214				c.driver.failWriteKind = ""
215			}
216			c.driver.mu.Unlock()
217			if fire {
218				return errors.New("forced write failure from test driver")
219			}
220		}
221		return nil
222	}
223	
224	// countingStmt carries the originating query so the fault configured for that
225	// statement's table fires on Exec.
226	type countingStmt struct {
227		driver.Stmt
228		driver *Driver
229		query  string
230	}
231	
232	func (s *countingStmt) Exec(args []driver.Value) (driver.Result, error) {
233		if kind := WriteKind(s.query); kind != "" {
234			s.driver.mu.Lock()
235			fire := s.driver.failWriteKind == kind
236			if fire {
237				s.driver.failWriteKind = ""
238			}
239			s.driver.mu.Unlock()
240			if fire {
241				return nil, errors.New("forced write failure from test driver")
242			}
243		}
244		return s.Stmt.Exec(args)
245	}
246	
247	type countingRows struct {
248		driver.Rows
249		driver *Driver
250		kind   string
251	}
252	
253	func (r *countingRows) Next(dest []driver.Value) error {
254		err := r.Rows.Next(dest)
255		if err == nil {
256			r.driver.mu.Lock()
257			r.driver.stats.rowsByKind[r.kind]++
258			r.driver.mu.Unlock()
259		}
260		return err
261	}
262	
263	// SelectKind classifies the store's read statements. Transaction control, DDL
264	// and PRAGMAs return the empty string and are never counted.
265	func SelectKind(query string) string {
266		s := strings.ToUpper(strings.TrimSpace(query))
267		if !strings.HasPrefix(s, "SELECT") {
268			return ""
269		}
270		switch {
271		case strings.Contains(s, "COUNT(*)"):
272			return "count"
273		case strings.Contains(s, "FROM COMPONENTS C"):
274			return "components"
275		case strings.Contains(s, "FROM DEPENDENCIES D"):
276			return "dependencies"
277		default:
278			return "sboms"
279		}
280	}
281	
282	// WriteKind classifies the store's INSERT statements so tests can target one
283	// detail-write step: "sboms", "components" or "dependencies". Every other
284	// statement returns the empty string.
285	func WriteKind(query string) string {
286		s := strings.ToUpper(strings.TrimSpace(query))
287		if !strings.HasPrefix(s, "INSERT INTO") {
288			return ""
289		}
290		switch {
291		case strings.HasPrefix(s, "INSERT INTO COMPONENTS"):
292			return "components"
293		case strings.HasPrefix(s, "INSERT INTO DEPENDENCIES"):
294			return "dependencies"
295		default:
296			return "sboms"
297		}
298	}
299	
300	func isRollback(query string) bool {
301		return strings.HasPrefix(strings.ToUpper(strings.TrimSpace(query)), "ROLLBACK")
302	}
303

